package com.campus.lostfound.service;
import com.campus.lostfound.domain.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.junit.jupiter.api.Assertions.*;
class HandoverTest {@Test void completionRequiresOwnerConfirmation(){User student=new User("Sam Student","sam@example.edu","hash","S1","Arts",Role.STUDENT);User staff=new User("Casey Staff","casey@example.edu","hash","F1","Operations",Role.STAFF);FoundReport report=new FoundReport("Blue bottle","Steel bottle","Other","Library",java.time.LocalDate.now(),null,staff,null,"Security","scratch on base");Claim claim=new Claim(report,student,"Mine","small sticker");claim.review(staff,true,"Verified");Handover handover=new Handover(claim,staff,"Security desk",Instant.now().plusSeconds(600));assertThrows(IllegalStateException.class,handover::complete);handover.confirmOwner();handover.complete();assertEquals(HandoverStatus.COMPLETED,handover.getStatus());}}
